+# preflight.yaml — prerequisites per stage/platform (read by melt/preflight.py).
+# Declarative so "is everything ready?" is data, not code. Paper: IEEE Access 2026.
+common:
+  python: ">=3.10"
+  packages: [numpy, scipy, soundfile, yaml, matplotlib]
+  writable: [results/raw, paper]
+  dataset_root: ./datasets
+
+stages:
+  # --- per-platform speedup/energy (run by reproduce.sh) ---
+  latency:    {device: [cuda, mps], datasets: [librispeech/libri6000]}
+  # energy uses NVML on CUDA (pynvml, via requirements-cuda.txt) and powermetrics
+  # on Apple MPS; pynvml is not listed here so Apple boxes are not blocked.
+  energy:     {device: [cuda, mps], datasets: [librispeech/libri6000]}
+  external:   {device: [cuda, mps], packages: [torchaudio, nnaudio, librosa],
+               datasets: [librispeech/libri6000]}
+  msweep:     {device: [cuda]}
+  batch:      {device: [cuda], datasets: [librispeech/libri6000]}
+  v100_power: {device: [cuda]}
+  # --- CUDA-only tasks (run by reproduce_*.sh) ---
+  whisper:     {device: [cuda], packages: [whisper, jiwer], datasets: [librispeech/test-clean]}
+  voxceleb:    {device: [cuda], packages: [scikit-learn], datasets: [voxceleb1/manifest.csv]}
+  equivalence: {device: [cuda], datasets: [librispeech/libri6000]}
+  # SPIRA-ACL2021 audio lives in pacientes/ and controle/ (the metadata CSV
+  # file_path column points there; loader resolves datasets/spira/<file_path>).
+  spira_train: {device: [cuda], packages: [librosa, scikit-learn, pandas],
+                datasets: [spira/metadata_train.csv, spira/metadata_test.csv,
+                           spira/pacientes, spira/controle]}
+  spira:       {device: [cuda], packages: [scikit-learn],
+                datasets: [spira/metadata_test.csv, spira/pacientes, spira/controle,
+                           spira/checkpoints]}
